#!/usr/bin/env python3
"""Turn a 32-byte raw Ed25519 public key into a C header: gen_pubkey_header.py public.raw pubkey.h"""
import sys

raw = open(sys.argv[1], "rb").read()
assert len(raw) == 32, "an Ed25519 public key is 32 bytes"
body = ",".join(f"0x{b:02x}" for b in raw)
open(sys.argv[2], "w").write(
    "/* generated by tools/gen_pubkey_header.py; do not edit */\n"
    "#pragma once\n#include <stdint.h>\n"
    f"static const uint8_t BOOT_PUBLIC_KEY[32] = {{{body}}};\n")
